import{_ as a,o as e,c as n,a3 as s}from"./chunks/framework.bvEHUNtb.js";const u=JSON.parse('{"title":"03 四象论","description":"从《周易》的哲学层与天文观测层，理解四象作为阴阳第一次分化的双重脉络。","frontmatter":{"title":"03 四象论","description":"从《周易》的哲学层与天文观测层，理解四象作为阴阳第一次分化的双重脉络。","category":"guide","outline":"deep","aliases":["四象论","阴阳四象","太阴太阳少阴少阳"]},"headers":[],"relativePath":"topics/traditional-wisdom/cosmology/four-symbols-theory.md","filePath":"topics/traditional-wisdom/cosmology/four-symbols-theory.md","lastUpdated":1786982540000}'),l={name:"topics/traditional-wisdom/cosmology/four-symbols-theory.md"};function i(p,t,r,o,d,c){return e(),n("div",null,[...t[0]||(t[0]=[s(`<h1 id="_03-·-四象论-阴阳的第一次分化" tabindex="-1">03 · 四象论：阴阳的第一次分化 <a class="header-anchor" href="#_03-·-四象论-阴阳的第一次分化" aria-label="Permalink to &quot;03 · 四象论：阴阳的第一次分化&quot;">​</a></h1><h2 id="版本与引用说明" tabindex="-1">版本与引用说明 <a class="header-anchor" href="#版本与引用说明" aria-label="Permalink to &quot;版本与引用说明&quot;">​</a></h2><p>本篇所引原典，以先秦至汉代文献为主要依据，区分哲学层（《周易》）与天文层（《史记·天官书》《淮南子》）两条来源脉络。后世注疏与个人解读均有标注。</p><hr><h2 id="一、四象在体系中的位置" tabindex="-1">一、四象在体系中的位置 <a class="header-anchor" href="#一、四象在体系中的位置" aria-label="Permalink to &quot;一、四象在体系中的位置&quot;">​</a></h2><div class="language-plain vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">plain</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>太极</span></span>
<span class="line"><span> └─ 阴阳</span></span>
<span class="line"><span>      ├─ 四象（本篇）← 阴阳的第一次分化</span></span>
<span class="line"><span>      │    ├─ 哲学层：太阴·太阳·少阴·少阳</span></span>
<span class="line"><span>      │    └─ 天文层：东青龙·西白虎·南朱雀·北玄武</span></span>
<span class="line"><span>      │         └─ 二十八星宿</span></span>
<span class="line"><span>      ├─ 五行</span></span>
<span class="line"><span>      └─ 八卦</span></span></code></pre></div><p>四象是整个传统体系中一个<strong>关键的分叉节点</strong>：</p><ul><li>向上，它是阴阳的直接延伸，是宇宙观的第二层分化；</li><li>向右，它生出八卦，是《周易》符号系统的前置逻辑；</li><li>向下，它落地为天文方位，成为二十八星宿、九宫、术数体系的坐标基础。</li></ul><p>理解四象，才能理解为什么&quot;东方属木&quot;&quot;北方属水&quot;——这不是任意规定，而是有其天文观测与哲学推演的双重根基。</p><hr><h2 id="二、原典依据-四象从哪里来" tabindex="-1">二、原典依据：四象从哪里来？ <a class="header-anchor" href="#二、原典依据-四象从哪里来" aria-label="Permalink to &quot;二、原典依据：四象从哪里来？&quot;">​</a></h2><h3 id="_2-1-哲学来源-《周易·系辞上传》" tabindex="-1">2.1 哲学来源：《周易·系辞上传》 <a class="header-anchor" href="#_2-1-哲学来源-《周易·系辞上传》" aria-label="Permalink to &quot;2.1 哲学来源：《周易·系辞上传》&quot;">​</a></h3><p>【原典】《周易·系辞上传》<br> 【原文】易有太极，是生两仪，两仪生四象，四象生八卦。<br> 【版本】王弼注本（三国·魏·王弼，226–249年）；今通行本<br> 【说明】这是四象在哲学层面最权威的出处。<br> &quot;两仪&quot;即阴阳，&quot;四象&quot;是阴阳的第一次组合分化，&quot;八卦&quot;则是四象的再次叠加。<br> 此处四象是纯粹的逻辑符号，尚无方位与神兽的含义。</p><h3 id="_2-2-符号结构-四象的爻象表达" tabindex="-1">2.2 符号结构：四象的爻象表达 <a class="header-anchor" href="#_2-2-符号结构-四象的爻象表达" aria-label="Permalink to &quot;2.2 符号结构：四象的爻象表达&quot;">​</a></h3><p>四象由两爻组合而成，是三爻八卦的前一步：</p><p>两仪（一爻）：</p><ul><li>阳爻 ———</li><li>阴爻 — —</li></ul><p>四象（两爻）：</p><ul><li>老阳（太阳），两阳叠加</li><li>少阴，阳下阴上</li><li>少阳，阴下阳上</li><li>老阴（太阴），两阴叠加</li></ul><p>【原典】《周易·系辞下传》<br> 【原文】阳卦多阴，阴卦多阳……<br> 【说明】老阳·老阴为&quot;极&quot;，是变爻的来源（筮法中老阳变阴、老阴变阳）；</p><p>少阳·少阴为&quot;稳&quot;，不变。这是四象在占筮实践中的直接应用。</p><h3 id="_2-3-天文来源-《史记·天官书》" tabindex="-1">2.3 天文来源：《史记·天官书》 <a class="header-anchor" href="#_2-3-天文来源-《史记·天官书》" aria-label="Permalink to &quot;2.3 天文来源：《史记·天官书》&quot;">​</a></h3><p>【原典】《史记·天官书》（西汉·司马迁，约公元前91年）<br> 【原文】东宫苍龙……南宫朱鸟……西宫咸池（白虎）……北宫玄武……<br> 【说明】司马迁在《天官书》中以四方星宫记载二十八宿，四象在此已完全天文化、方位化，成为星空坐标系的四个象限。</p><p>这是四象从哲学符号演变为天文工具的重要文献证据。</p><h3 id="_2-4-方位神兽-《礼记·曲礼上》" tabindex="-1">2.4 方位神兽：《礼记·曲礼上》 <a class="header-anchor" href="#_2-4-方位神兽-《礼记·曲礼上》" aria-label="Permalink to &quot;2.4 方位神兽：《礼记·曲礼上》&quot;">​</a></h3><p>【原典】《礼记·曲礼上》（先秦礼制文献，汉代郑玄注）<br> 【原文】行，前朱鸟而后玄武，左青龙而右白虎。<br> 【说明】此处四象已完全方位化，用于军阵与礼仪的空间规范。<br> 面南而立：前（南）朱雀、后（北）玄武、左（东）青龙、右（西）白虎。<br> 这是四象方位系统在礼制层面的最早明确记载之一。</p><h3 id="_2-5-天文历法-《淮南子·天文训》" tabindex="-1">2.5 天文历法：《淮南子·天文训》 <a class="header-anchor" href="#_2-5-天文历法-《淮南子·天文训》" aria-label="Permalink to &quot;2.5 天文历法：《淮南子·天文训》&quot;">​</a></h3><p>【原典】《淮南子·天文训》（西汉·刘安，约公元前139年）<br> 【原文】天神之贵者，莫贵于青龙，或曰天一，或曰太阴……<br> （另） 日行一度，以周于天……二十八宿为经，<br> 东方角、亢、氐、房、心、尾、箕……<br> 【说明】《淮南子》将四象与二十八星宿、历法、季节完整整合，是汉代宇宙论的集大成文献。<br> 四象在此不仅是方位符号，更是时间坐标——<br> 春观东方青龙，夏观南方朱雀，秋观西方白虎，冬观北方玄武。</p><h2 id="三、四象的双重身份-哲学层-vs-天文层" tabindex="-1">三、四象的双重身份：哲学层 vs 天文层 <a class="header-anchor" href="#三、四象的双重身份-哲学层-vs-天文层" aria-label="Permalink to &quot;三、四象的双重身份：哲学层 vs 天文层&quot;">​</a></h2><p>四象在传统体系中承担两套完全不同的功能，必须分开理解：</p><h3 id="_3-1-哲学层-阴阳的逻辑分化" tabindex="-1">3.1 哲学层：阴阳的逻辑分化 <a class="header-anchor" href="#_3-1-哲学层-阴阳的逻辑分化" aria-label="Permalink to &quot;3.1 哲学层：阴阳的逻辑分化&quot;">​</a></h3><div class="language-plain vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">plain</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>功能：描述宇宙变化的四种基本状态</span></span>
<span class="line"><span>符号：老阳·少阴·少阳·老阴</span></span>
<span class="line"><span>对应：生长·收敛·萌发·归藏</span></span>
<span class="line"><span>本质：这是一套抽象的变化模型，不涉及具体方位</span></span>
<span class="line"><span>来源：《周易·系辞》</span></span></code></pre></div><table tabindex="0"><thead><tr><th style="text-align:center;">四象</th><th style="text-align:center;">爻象</th><th style="text-align:center;">性质</th><th style="text-align:center;">对应状态</th><th style="text-align:center;">五行对应</th></tr></thead><tbody><tr><td style="text-align:center;">老阳（太阳）</td><td style="text-align:center;">——— ———</td><td style="text-align:center;">阳之极</td><td style="text-align:center;">盛极将变</td><td style="text-align:center;">火</td></tr><tr><td style="text-align:center;">少阳</td><td style="text-align:center;">———<br>— —</td><td style="text-align:center;">阳之初</td><td style="text-align:center;">生发上升</td><td style="text-align:center;">木</td></tr><tr><td style="text-align:center;">少阴</td><td style="text-align:center;">— — ———</td><td style="text-align:center;">阴之初</td><td style="text-align:center;">收敛内化</td><td style="text-align:center;">金</td></tr><tr><td style="text-align:center;">老阴（太阴）</td><td style="text-align:center;">— — — —</td><td style="text-align:center;">阴之极</td><td style="text-align:center;">归藏潜伏</td><td style="text-align:center;">水</td></tr></tbody></table><p>【个人解读】老阳·老阴是&quot;极态&quot;，是变化的临界点；<br> 少阳·少阴是&quot;动态&quot;，是变化的过程。<br> 这与中医&quot;亢则害，承乃制&quot;的思想一脉相承——极则必反，稳则可持续。</p><h3 id="_3-2-天文层-四方星空的坐标划分" tabindex="-1">3.2 天文层：四方星空的坐标划分 <a class="header-anchor" href="#_3-2-天文层-四方星空的坐标划分" aria-label="Permalink to &quot;3.2 天文层：四方星空的坐标划分&quot;">​</a></h3><p>功能：将天球划分为四个方位象限，作为星空坐标</p><p>符号：青龙·白虎·朱雀·玄武</p><p>对应：东·西·南·北</p><p>本质：这是一套天文观测工具，有具体的星宿对应</p><p>来源：《史记·天官书》《淮南子·天文训》</p><table tabindex="0"><thead><tr><th style="text-align:center;">四象</th><th style="text-align:center;">方位</th><th style="text-align:center;">神兽</th><th style="text-align:center;">季节</th><th style="text-align:center;">五行</th><th style="text-align:center;">所领星宿数</th></tr></thead><tbody><tr><td style="text-align:center;">东方苍龙</td><td style="text-align:center;">东</td><td style="text-align:center;">青龙</td><td style="text-align:center;">春</td><td style="text-align:center;">木</td><td style="text-align:center;">七宿</td></tr><tr><td style="text-align:center;">南方朱鸟</td><td style="text-align:center;">南</td><td style="text-align:center;">朱雀</td><td style="text-align:center;">夏</td><td style="text-align:center;">火</td><td style="text-align:center;">七宿</td></tr><tr><td style="text-align:center;">西方白虎</td><td style="text-align:center;">西</td><td style="text-align:center;">白虎</td><td style="text-align:center;">秋</td><td style="text-align:center;">金</td><td style="text-align:center;">七宿</td></tr><tr><td style="text-align:center;">北方玄武</td><td style="text-align:center;">北</td><td style="text-align:center;">玄武</td><td style="text-align:center;">冬</td><td style="text-align:center;">水</td><td style="text-align:center;">七宿</td></tr></tbody></table><p>【考据说明】&quot;玄武&quot;之名，在先秦文献中写作&quot;玄冥&quot;或&quot;玄武&quot;，形象为龟蛇合体，象征北方水气与冬藏之性。<br> 四神兽的图像在汉代画像砖、马王堆帛书中均有出土实物佐证，并非纯粹的文字传说。</p><h2 id="四、四象的演化史-从符号到神话" tabindex="-1">四、四象的演化史：从符号到神话 <a class="header-anchor" href="#四、四象的演化史-从符号到神话" aria-label="Permalink to &quot;四、四象的演化史：从符号到神话&quot;">​</a></h2><p>四象的形成，是一个跨越数百年的历史过程，并非一夕建构：</p><div class="language-plain vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">plain</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>商周时期</span></span>
<span class="line"><span>  └─ 甲骨文中已有东西南北四方祭祀记录</span></span>
<span class="line"><span>     （殷墟甲骨：&quot;东方曰析，凤曰劦；南方曰夹，风曰凯……&quot;）</span></span>
<span class="line"><span>     此时四方有名，神兽形象尚未固定</span></span>
<span class="line"><span></span></span>
<span class="line"><span>春秋战国</span></span>
<span class="line"><span>  └─ 《礼记·曲礼》出现&quot;前朱鸟后玄武，左青龙右白虎&quot;</span></span>
<span class="line"><span>     四象方位系统基本定型</span></span>
<span class="line"><span>     《楚帛书》（约公元前4世纪）中已有四方神兽图像</span></span>
<span class="line"><span></span></span>
<span class="line"><span>西汉</span></span>
<span class="line"><span>  └─ 《史记·天官书》将四象与二十八星宿完整对应</span></span>
<span class="line"><span>     《淮南子·天文训》整合四象、历法、季节为完整宇宙论</span></span>
<span class="line"><span>     马王堆汉墓（公元前168年）出土帛画，四神兽图像完整</span></span>
<span class="line"><span></span></span>
<span class="line"><span>东汉以后</span></span>
<span class="line"><span>  └─ 四象进入道教神系，神兽人格化为神明</span></span>
<span class="line"><span>     与五行、干支、奇门、风水体系全面融合</span></span></code></pre></div><p>【学术说明】最初只有&quot;二象&quot;（青龙与白虎），东周之后逐渐发展为完整的四象体系，并在东周至汉代之间才与二十八星宿产生系统性关联。<br> 这一演化过程有考古文物与文献双重支撑，并非神话传说。</p><h2 id="五、四象与五行的关系-为什么中间缺一个" tabindex="-1">五、四象与五行的关系：为什么中间缺一个？ <a class="header-anchor" href="#五、四象与五行的关系-为什么中间缺一个" aria-label="Permalink to &quot;五、四象与五行的关系：为什么中间缺一个？&quot;">​</a></h2><p>细心的读者会发现：四象对应四方，五行有五个，中间差了&quot;土&quot;。</p><div class="language-plain vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">plain</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>东方青龙 = 木</span></span>
<span class="line"><span>南方朱雀 = 火</span></span>
<span class="line"><span>西方白虎 = 金</span></span>
<span class="line"><span>北方玄武 = 水</span></span>
<span class="line"><span>中央？？？= 土</span></span></code></pre></div><p>【原典】《黄帝内经·素问·金匮真言论》<br> 【原文】中央黄色，入通于脾……其应四时，上为镇星，是以知病之在肉也。<br> 【说明】&quot;土&quot;居中央，不主一方，而是<strong>四方的枢纽与转化者</strong>。<br> 这正是五行&quot;土居中央，寄旺四季&quot;思想的来源——<br> 土不独占一季，而是在每季末十八天发挥作用，贯穿全年。</p><p><strong>四象（四方）+ 中央土 = 五行完整体系</strong></p><p>这不是缺漏，而是设计：</p><p>四象描述&quot;运动与方向&quot;，土描述&quot;承载与转化&quot;，两者合一，才是完整的宇宙坐标系。</p><h2 id="六、四象在各体系中的接口" tabindex="-1">六、四象在各体系中的接口 <a class="header-anchor" href="#六、四象在各体系中的接口" aria-label="Permalink to &quot;六、四象在各体系中的接口&quot;">​</a></h2><p>四象是传统体系中使用频率极高的&quot;公共接口&quot;，几乎所有后续体系都要调用：</p><table tabindex="0"><thead><tr><th style="text-align:left;">体系</th><th style="text-align:left;">四象的具体用途</th></tr></thead><tbody><tr><td style="text-align:left;"><strong>《周易》</strong></td><td style="text-align:left;">四象生八卦，是卦象推演的逻辑前置</td></tr><tr><td style="text-align:left;"><strong>二十八星宿</strong></td><td style="text-align:left;">四象各领七宿，是星空坐标的分区依据</td></tr><tr><td style="text-align:left;"><strong>奇门遁甲</strong></td><td style="text-align:left;">九宫方位以四象为基础定东西南北</td></tr><tr><td style="text-align:left;"><strong>风水（堪舆）</strong></td><td style="text-align:left;">峦头四神兽：前朱雀·后玄武·左青龙·右白虎</td></tr><tr><td style="text-align:left;"><strong>中医</strong></td><td style="text-align:left;">四方对应四脏（肝·心·肺·肾），土居中央对应脾</td></tr><tr><td style="text-align:left;"><strong>紫微斗数</strong></td><td style="text-align:left;">四象方位影响宫位能量属性</td></tr><tr><td style="text-align:left;"><strong>六壬</strong></td><td style="text-align:left;">四课三传中方位判断以四象为参照</td></tr></tbody></table><h2 id="七、现代解读-四象是一套-坐标系思维" tabindex="-1">七、现代解读：四象是一套&quot;坐标系思维&quot; <a class="header-anchor" href="#七、现代解读-四象是一套-坐标系思维" aria-label="Permalink to &quot;七、现代解读：四象是一套&quot;坐标系思维&quot;&quot;">​</a></h2><p>抛开神话外衣，四象的本质是什么？</p><blockquote><p><strong>四象是古人建立的第一套完整坐标系。</strong></p></blockquote><p>在没有经纬度、没有GPS的时代，古人用天空中的星宿群来定位：</p><ul><li>你在哪里？→ 看你头顶是哪个星宫</li><li>现在什么季节？→ 看黄昏时哪个神兽升起</li><li>这块地的方位？→ 用青龙白虎朱雀玄武来标注</li></ul><p>这套坐标系，同时承载了**空间（方位）、时间（季节）、能量（五行）**三个维度，是一套极为高效的古代信息压缩系统。</p><p>用现代语言说：四象是一个<strong>多维度的坐标索引</strong>，将天文、地理、时间、能量统一编码在四个符号之中。</p><h3 id="四象-vs-数学四象限-有联系吗" tabindex="-1">四象 vs 数学四象限：有联系吗？ <a class="header-anchor" href="#四象-vs-数学四象限-有联系吗" aria-label="Permalink to &quot;四象 vs 数学四象限：有联系吗？&quot;">​</a></h3><p>一句话结论：命名上有联系，本质上是两套独立系统——但底层思维逻辑高度相似。</p><h4 id="命名的联系-直接借用" tabindex="-1">命名的联系：直接借用 <a class="header-anchor" href="#命名的联系-直接借用" aria-label="Permalink to &quot;命名的联系：直接借用&quot;">​</a></h4><p>数学里的&quot;四象限&quot;（Quadrant）这个<strong>中文译名</strong>，就是直接借用了《周易》的&quot;四象&quot;概念：</p><div class="language-plain vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">plain</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>西方原词：Quadrant = 四分之一（拉丁语 quadrans）</span></span>
<span class="line"><span>中文翻译：四象限</span></span>
<span class="line"><span>         ↑</span></span>
<span class="line"><span>         直接取自&quot;两仪生四象&quot;的&quot;四象&quot;意象</span></span></code></pre></div><p>这不是巧合，是近代中国数学翻译者有意为之的文化对接。</p><h4 id="结构上的相似-惊人的对应" tabindex="-1">结构上的相似：惊人的对应 <a class="header-anchor" href="#结构上的相似-惊人的对应" aria-label="Permalink to &quot;结构上的相似：惊人的对应&quot;">​</a></h4><div class="language-plain vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">plain</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>《周易》四象                数学四象限</span></span>
<span class="line"><span>──────────────────────────────────────────</span></span>
<span class="line"><span>太阳（老阳）                第一象限（+x, +y）</span></span>
<span class="line"><span>少阴（少阴）                第二象限（-x, +y）</span></span>
<span class="line"><span>少阳（少阳）                第三象限（-x, -y）</span></span>
<span class="line"><span>太阴（老阴）                第四象限（+x, -y）</span></span></code></pre></div><p>共同点：</p><ul><li>都是&quot;二元对立&quot;产生&quot;四分&quot;</li><li>都以&quot;中心原点/太极&quot;为基准</li><li>都用于&quot;定位&quot;与&quot;分类&quot;</li><li>都是穷举性的——四个区域覆盖全部可能</li></ul><h4 id="本质上的差异-两套不同的世界观" tabindex="-1">本质上的差异：两套不同的世界观 <a class="header-anchor" href="#本质上的差异-两套不同的世界观" aria-label="Permalink to &quot;本质上的差异：两套不同的世界观&quot;">​</a></h4><table tabindex="0"><thead><tr><th style="text-align:left;">维度</th><th style="text-align:left;">《周易》四象</th><th style="text-align:left;">数学四象限</th></tr></thead><tbody><tr><td style="text-align:left;"><strong>目的</strong></td><td style="text-align:left;">描述变化状态与趋势</td><td style="text-align:left;">定位空间中的点</td></tr><tr><td style="text-align:left;"><strong>维度</strong></td><td style="text-align:left;">时间性（动态·周期）</td><td style="text-align:left;">空间性（静态·坐标）</td></tr><tr><td style="text-align:left;"><strong>核心逻辑</strong></td><td style="text-align:left;">阴阳消长（量变）</td><td style="text-align:left;">正负轴交叉（二元切割）</td></tr><tr><td style="text-align:left;"><strong>有无中心</strong></td><td style="text-align:left;">太极为本，四象是流</td><td style="text-align:left;">原点是参考，无哲学含义</td></tr><tr><td style="text-align:left;"><strong>能否互转</strong></td><td style="text-align:left;">四象可继续演化为八卦</td><td style="text-align:left;">象限是终态，不再演化</td></tr></tbody></table><h4 id="四、最深的共鸣-二进制的底层" tabindex="-1">四、最深的共鸣：二进制的底层 <a class="header-anchor" href="#四、最深的共鸣-二进制的底层" aria-label="Permalink to &quot;四、最深的共鸣：二进制的底层&quot;">​</a></h4><p>这里有一个更有趣的连接——莱布尼茨（Leibniz）1703年读到传教士带回的《周易》六十四卦图后惊呼：这不就是二进制！</p><p>所以更准确的说法是：</p><p>《周易》四象与数学四象限，<strong>不是同一棵树上的两根枝</strong>，而是<strong>两棵树，根系在更深处相连</strong>。那个更深的根，叫做&quot;<strong>二元对立产生秩序</strong>&quot;，是人类思维面对复杂世界时，最本能的归纳方式。</p><h2 id="八、承前启后-四象的上下游" tabindex="-1">八、承前启后：四象的上下游 <a class="header-anchor" href="#八、承前启后-四象的上下游" aria-label="Permalink to &quot;八、承前启后：四象的上下游&quot;">​</a></h2><h3 id="上游" tabindex="-1">上游 <a class="header-anchor" href="#上游" aria-label="Permalink to &quot;上游&quot;">​</a></h3><p>阴阳是一分为二，四象是二分为四。</p><p>阴阳给了&quot;对立&quot;，四象给了&quot;方向&quot;。</p><p>没有阴阳，四象无从生；</p><p>有了四象，宇宙才有了东西南北、春夏秋冬。</p><h3 id="下游" tabindex="-1">下游 <a class="header-anchor" href="#下游" aria-label="Permalink to &quot;下游&quot;">​</a></h3><p>方向一：八卦</p><pre><code>四象再次叠加一爻，生出八卦。

八卦是四象的符号延伸，

先天八卦的方位排列，正是以四象为基础旋转而来。
</code></pre><p>方向二：二十八星宿</p><pre><code>四象落地为天文坐标，每象各领七宿，构成完整的星空地图。

这是四象从哲学进入实用天文的关键一跳。
</code></pre><p>先人不是在&quot;算命&quot;而是在用当时最先进的方式构建一套&quot;宇宙坐标系&quot;。</p><p>四象 = 古代版的多维坐标系</p><p>只不过它的轴不是x/y ，而是：阴阳 × 时间 × 方位 × 能量状态</p><p>这也是为什么四象能同时对接八卦（符号演化）和二十八星宿（天文坐标）——它本质上就是一个<strong>可扩展的分类框架</strong>，跟现代数学的坐标思想，殊途同归。</p><h2 id="九、本章小结" tabindex="-1">九、本章小结 <a class="header-anchor" href="#九、本章小结" aria-label="Permalink to &quot;九、本章小结&quot;">​</a></h2><p>四象，是传统智慧体系中一个常被忽略、却极为关键的节点。</p><p>它不是一个独立的&quot;知识点&quot;，而是一个<strong>枢纽</strong>：</p><ul><li>在哲学上，它是阴阳分化的第一步，是八卦的前置逻辑；</li><li>在天文上，它是星空坐标的四个象限，是二十八星宿的宗主；</li><li>在应用上，它是风水、奇门、中医、六壬共用的方位语言。</li></ul><p>理解了四象，你就理解了为什么传统体系中&quot;方位&quot;如此重要——<br> 因为方位不只是空间概念，它同时携带着时间、能量、变化趋势的全部信息。</p><hr><p><em>文档版本：v1.0 · 四象论 ｜ 2026年7月 ｜ 持续更新中</em></p>`,101)])])}const g=a(l,[["render",i]]);export{u as __pageData,g as default};
